REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.is_staff(uuid) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;

DROP POLICY "Public reads active categories" ON public.categories;
DROP POLICY "Public reads active collections" ON public.collections;
DROP POLICY "Public reads published products" ON public.products;
DROP POLICY "Public reads images of published products" ON public.product_images;
DROP POLICY "Public reads active lookbook" ON public.lookbook_items;
DROP POLICY "Public reads active homepage sections" ON public.homepage_sections;
DROP POLICY "Public reads public settings" ON public.site_settings;

CREATE POLICY "Visible categories" ON public.categories FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY "Visible collections" ON public.collections FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY "Published products" ON public.products FOR SELECT TO anon, authenticated USING (status = 'published');
CREATE POLICY "Images of published products" ON public.product_images FOR SELECT TO anon, authenticated
  USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id = product_id AND p.status = 'published'));
CREATE POLICY "Visible lookbook" ON public.lookbook_items FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY "Visible homepage sections" ON public.homepage_sections FOR SELECT TO anon, authenticated USING (is_active);
CREATE POLICY "Public settings" ON public.site_settings FOR SELECT TO anon, authenticated USING (is_public);

DO $$
DECLARE r jsonb; pid uuid; img text; i int;
BEGIN
FOR r IN SELECT * FROM jsonb_array_elements('[{"s":"celestial-diamond-ring","n":"Celestial Ring","d":"Designed around a fluid silhouette, the Celestial Ring balances warm 18K gold with a carefully set natural diamond, flanked by two smaller stones that catch the light as the hand moves.","c":"rings","k":"celestial","p":84500,"m":"18K Gold","st":"Diamond","o":["Engagement","Anniversary"],"a":"in-stock","w":"3.8 g","dm":"Band 1.8 mm","ce":"IGI certified · BIS Hallmarked","t":["rings","18k gold","diamond","engagement","anniversary"],"f":true,"nw":false,"b":true,"l":false,"at":"2026-03-02","i":["collection-1.jpg","story.jpg","collection-1.jpg","craft.jpg"]},{"s":"heritage-pearl-jhumka","n":"Heritage Jhumka","d":"A temple-bell jhumka reconsidered — hand-pierced 22K gold, a crown of polki, and a fringe of keshi pearls that moves softly with every turn.","c":"earrings","k":"heritage","p":126000,"m":"22K Gold","st":"Pearl","o":["Statement","Bridal"],"a":"in-stock","w":"18.4 g","dm":"48 mm drop","ce":"BIS Hallmarked","t":["earrings","22k gold","pearl","statement","bridal"],"f":true,"nw":false,"b":true,"l":false,"at":"2026-02-11","i":["collection-2.jpg","lookbook.jpg","craft.jpg","story.jpg"]},{"s":"solitaire-diamond-pendant","n":"Solitaire Pendant","d":"A single round brilliant held in four slender claws, suspended from a fine cable chain. Made to be worn every day and rarely taken off.","c":"pendants","k":"celestial","p":98000,"m":"18K Gold","st":"Diamond","o":["Everyday","Gifting"],"a":"in-stock","w":"2.6 g","dm":"Chain 45 cm","ce":"IGI certified · BIS Hallmarked","t":["pendants","18k gold","diamond","everyday","gifting"],"f":true,"nw":false,"b":false,"l":false,"at":"2026-01-20","i":["product-pendant.jpg","hero.jpg","craft.jpg","story.jpg"]},{"s":"aurum-engraved-bangles","n":"Aurum Bangles","d":"A pair of slim bangles, each hand-engraved with a woven pattern drawn from old Banarasi borders. Made to order in your size.","c":"bangles","k":"aurum","p":null,"m":"22K Gold","st"