estial","p":245000,"m":"White Gold","st":"Diamond","o":["Anniversary","Gifting"],"a":"in-stock","w":"9.6 g","dm":"17 cm","ce":"IGI certified · BIS Hallmarked","t":["bracelets","white gold","diamond","anniversary","gifting"],"f":false,"nw":true,"b":false,"l":false,"at":"2026-08-22","i":["p-tennis-bracelet.jpg","story.jpg","craft.jpg","craft-design.jpg"]},{"s":"monarch-onyx-signet","n":"Monarch Signet","d":"A substantial signet in polished 18K gold with a domed black onyx face. Can be engraved on the inner band.","c":"mens","k":"aurum","p":92000,"m":"18K Gold","st":"Other","o":["Everyday","Gifting"],"a":"made-to-order","w":"11.2 g","dm":"Face 14 mm","ce":"BIS Hallmarked","t":["mens","18k gold","other","everyday","gifting"],"f":false,"nw":false,"b":false,"l":false,"at":"2026-05-09","i":["p-signet.jpg","craft.jpg","story.jpg","craft-design.jpg"]},{"s":"maharani-bridal-choker","n":"Maharani Choker","d":"Uncut polki in kundan settings, carved emerald beads and a fringe of pearls — a bridal heirloom made over twelve weeks by a single karigar.","c":"bridal","k":"heritage","p":null,"m":"22K Gold","st":"Emerald","o":["Bridal","Statement"],"a":"made-to-order","w":"96.0 g","dm":"Adjustable","ce":"IGI certified · BIS Hallmarked","t":["bridal","22k gold","emerald","bridal","statement"],"f":true,"nw":false,"b":false,"l":true,"at":"2026-06-30","i":["p-bridal-choker.jpg","lookbook.jpg","craft.jpg","story.jpg"]},{"s":"nila-sapphire-pendant","n":"Nila Pendant","d":"A pear-cut Ceylon sapphire in a three-claw platinum setting, on a fine platinum chain.","c":"pendants","k":"celestial","p":136000,"m":"Platinum","st":"Sapphire","o":["Anniversary","Gifting"],"a":"in-stock","w":"3.1 g","dm":"Stone 10 × 7 mm","ce":"IGI certified · BIS Hallmarked","t":["pendants","platinum","sapphire","anniversary","gifting"],"f":false,"nw":true,"b":false,"l":false,"at":"2026-09-20","i":["p-sapphire-pendant.jpg","hero.jpg","craft.jpg","story.jpg"]},{"s":"dune-rose-gold-hoops","n":"Dune Hoops","d":"Sculptural hoops in rose gold, twisted like wind-shaped sand. Light to wear, bold to look at.","c":"earrings","k":"aurum","p":58000,"m":"Rose Gold","st":"Other","o":["Everyday","Statement"],"a":"in-stock","w":"8.4 g","dm":"28 mm","ce":"BIS Hallmarked","t":["earrings","rose gold","other","everyday","statement"],"f":false,"nw":true,"b":false,"l":false,"at":"2026-09-25","i":["p-rose-hoops.jpg","lookbook-2.jpg","craft.jpg","story.jpg"]},{"s":"panna-emerald-drop-necklace","n":"Panna Necklace","d":"A pear-shaped emerald in a bezel of 22K gold, crowned with a single diamond and hung on a fine trace chain.","c":"necklaces","k":"aurum","p":112000,"m":"22K Gold","st":"Emerald","o":["Anniversary","Gifting"],"a":"in-stock","w":"5.4 g","dm":"Chain 45 cm","ce":"IGI certified · BIS Hallmarked","t":["necklaces","22k gold","emerald","anniversary","gifting"],"f":false,"nw":false,"b":true,"l":false,"at":"2026-03-28","i":["collection-3.jpg","lookbook-3.jpg","craft.jpg","story.jpg"]},{"s":"solace-diamond-band","n":"Solace Band","d":"A whisper-thin band set with a single small diamond. Designed to be stacked, or worn alone.","c":"rings","k":"celestial","p":22500,"m":"18K Gold","st":"Diamond","o":["Everyday","Gifting"],"a":"in-stock","w":"1.6 g","dm":"Band 1.4 mm","ce":"IGI certified · BIS Hallmarked","t":["rings","18k gold","diamond","everyday","gifting"],"f":false,"nw":false,"b":false,"l":false,"at":"2026-02-02","i":["story.jpg","collection-1.jpg","craft.jpg","craft-design.jpg"]},{"s":"vivaah-bridal-chandbali","n":"Vivaah Chandbali","d":"Crescent chandbalis in hand-worked 22K gold, edged with seed pearls and finished with pearl drops.","c":"bridal","k":"heritage","p":285000,"m":"22K Gold","st":"Pearl","o":["Bridal"],"a":"made-to-order","w":"34.0 g (pair)","dm":"72 mm drop","ce":"BIS Hallmarked","t":["bridal","22k gold","pearl","bridal"],"f":false,"nw":false,"b":true,"l":false,"at":"2026-07-14","i":["lookbook.jpg","collection-2.jpg","craft.jpg","story.jpg"]},{"s":"keystone-gold-cuff","n":"Keystone Cuff","d":"An open cuff in brushed 18K gold with a softly squared profile. Shapes gently to the wrist.","c":"bracelets","k":"aurum","p":48000,"m":"18K Gold","st":"Other","o":["Everyday","Statement"],"a":"in-stock","w":"12.8 g","dm":"6 mm wide","ce":"BIS Hallmarked","t":["bracelets","18k gold","other","everyday","statement"],"f":false,"nw":false,"b":false,"l":false,"at":"2026-05-30","i":["product-bangle.jpg","story.jpg","craft.jpg","craft-design.jpg"]}]'::jsonb)
LOOP
  INSERT INTO public.products (slug,name,description,category_id,collection_id,price,price_on_request,metal,stone,occasions,availability,weight,dimensions,certification,tags,status,is_featured,is_new,is_bestseller,is_limited,created_at)
  VALUES (r->>'s', r->>'n', r->>'d',
    (SELECT id FROM public.categories WHERE slug = r->>'c'),
    (SELECT id FROM public.collections WHERE slug = r->>'k'),
    (r->>'p')::numeric, (r->'p') = 'null'::jsonb, r->>'m', r->>'st',
    ARRAY(SELECT jsonb_array_elements_text(r->'o')), r->>'a', r->>'w', r->>'dm', r->>'ce',
    ARRAY(SELECT jsonb_array_elements_text(r->'t')), 'published',
    (r->>'f')::boolean, (r->>'nw')::boolean, (r->>'b')::boolean, (r->>'l')::boolean, (r->>'at')::timestamptz)
  RETURNING id INTO pid;
  i := 0;
  FOR img IN SELECT jsonb_array_elements_text(r->'i') LOOP
    INSERT INTO public.product_images (product_id, image_url, storage_path, alt_text, sort_order, is_primary)
    VALUES (pid, 'https://gwtuegmszbuvkzlcfpvy.supabase.co/storage/v1/object/public/products/library/' || img, 'library/' || img,
      (r->>'n') || CASE WHEN i = 0 THEN '' ELSE ' — view ' || (i + 1) END, i, i = 0);
    i := i + 1;
  END LOOP;
END LOOP;
END $$;

